13|/**
14| * Forensic, user-directed export, not an automatic replay/import format. The
15| * entire ordered Outbox and every staged Blob are included; never claim success
16| * after truncating an image or omitting a pending operation.
17| */
18|export async function buildPendingWorkExport(
19|  store: Pick<OutboxStore, 'list'> & Pick<MediaOutboxStore, 'listMedia'>,
20|  now = new Date(),
21|): Promise<PendingWorkExport> {
22|  const [operations, uploads] = await Promise.all([store.list(), store.listMedia()]);
23|  const totalBytes = uploads.reduce((total, upload) => total + upload.byteLength, 0);
24|  if (totalBytes > MAX_EXPORT_MEDIA_BYTES) {
25|    throw new Error('Pending images exceed the safe single-file export limit (64 MiB); keep the device intact and sync first');
26|  }
27|  const media: PendingWorkExport['media'] = [];
28|  for (const { blob, ...upload } of uploads) {
29|    if (blob.size !== upload.byteLength) {
30|      throw new Error(`Staged image ${upload.uploadId} has a byte-length mismatch; refusing an incomplete export`);
31|    }
32|    const bytes = new Uint8Array(await blob.arrayBuffer());
33|    let binary = '';
34|    for (let offset = 0; offset < bytes.length; offset += 16_384) {
35|      binary += String.fromCharCode(...bytes.subarray(offset, offset + 16_384));
36|    }
37|    media.push({ ...upload, base64: btoa(binary) });
38|  }
39|  return { format: 't3-pending-work-v1', exportedAt: now.toISOString(), operations, media };
