30|/**
31| * Browser-backed offline storage. Snapshot generations and the durable Outbox
32| * use separate object stores, so snapshot pruning cannot delete queued intent.
33| */
34|export function createIndexedDbOfflineStore(
35|  options: IndexedDbOfflineStoreOptions = {},
36|): IndexedDbOfflineStore {
37|  const factory = options.indexedDB ?? globalThis.indexedDB;
38|  if (factory === undefined) throw new Error('IndexedDB is unavailable');
39|  const databaseName = options.databaseName ?? DEFAULT_OFFLINE_DATABASE_NAME;
40|  let databasePromise: Promise<IDBDatabase> | null = null;
41|
42|  function open(): Promise<IDBDatabase> {
43|    if (databasePromise !== null) return databasePromise;
44|    databasePromise = new Promise((resolve, reject) => {
45|      const request = factory.open(databaseName, DATABASE_VERSION);
46|      request.onupgradeneeded = () => {
47|        const database = request.result;
48|        if (!database.objectStoreNames.contains(GENERATIONS_STORE)) {
49|          database.createObjectStore(GENERATIONS_STORE);
50|        }
51|        if (!database.objectStoreNames.contains(META_STORE)) {
52|          database.createObjectStore(META_STORE);
53|        }
54|        if (!database.objectStoreNames.contains(OUTBOX_STORE)) {
55|          const outbox = database.createObjectStore(OUTBOX_STORE, {
56|            keyPath: 'sequence',
57|            autoIncrement: true,
58|          });
59|          outbox.createIndex(OUTBOX_OPERATION_ID_INDEX, 'opId', { unique: true });
60|        }
61|        if (!database.objectStoreNames.contains(MEDIA_OUTBOX_STORE)) {
62|          const media = database.createObjectStore(MEDIA_OUTBOX_STORE, { keyPath: 'uploadId' });
63|          media.createIndex('entryUid', 'entryUid', { unique: false });
