65|      };
66|      request.onsuccess = () => {
67|        request.result.onversionchange = () => request.result.close();
68|        resolve(request.result);
69|      };
70|      request.onerror = () => {
71|        databasePromise = null;
72|        reject(request.error ?? new Error('Failed to open offline storage'));
73|      };
74|      request.onblocked = () => {
75|        databasePromise = null;
76|        reject(new Error('Offline storage upgrade is blocked by another T3 tab'));
77|      };
78|    });
79|    return databasePromise;
80|  }
