43|export async function cleanupAbandonedSyncMediaStaging(
44|  assetRoot: string,
45|  options: { now?: number; maxAgeMs?: number } = {},
46|): Promise<number> {
47|  const now = options.now ?? Date.now();
48|  const maxAgeMs = options.maxAgeMs ?? STAGING_MAX_AGE_MS;
49|  if (!Number.isFinite(maxAgeMs) || maxAgeMs <= 0) throw new Error('Invalid staging retention');
50|  const entriesRoot = join(assetRoot, 'entries');
51|  let entries;
52|  try {
53|    entries = await readdir(entriesRoot, { withFileTypes: true });
54|  } catch (error) {
55|    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return 0;
56|    throw error;
57|  }
58|  let removed = 0;
59|  for (const entry of entries) {
60|    if (!entry.isDirectory() || !/^[1-9][0-9]*$/.test(entry.name)) continue;
61|    for (const [directory, pattern] of [
62|      [join(entriesRoot, entry.name), STAGED_SOURCE],
63|      [join(entriesRoot, entry.name, 'thumbnails'), STAGED_THUMBNAIL],
64|    ] as const) {
65|      let files;
66|      try {
67|        files = await readdir(directory, { withFileTypes: true });
68|      } catch (error) {
69|        if ((error as NodeJS.ErrnoException).code === 'ENOENT') continue;
70|        throw error;
71|      }
